/* ---------- шильдики сторон ---------- */
function partyType(l,party){var t=party==='obligor'?(l.obligor_type||(l.counterparty&&l.counterparty.type)):(l.seller_type||(l.debtor&&l.debtor.type));t=t?String(t).trim().toUpperCase():'';return /^(ЮЛ|ИП|ФЛ)$/.test(t)?t:''}
