/* для строки шильдиков EV_UI.card_badges (bLine): плоские .tag без вложенных span, порядок и «+N» считает bLine */
function listTags(l,scope){return badges(l,scope).map(function(b){var I=B.icon||{};return '<span class="tag lcbt '+(b.tone==='bad'?'lcstop':'lcwarn')+'" data-lcb="'+esc(b.id)+'" title="'+esc(b.label+' · '+b.tip)+'" aria-label="'+esc(b.label+'. '+b.tip)+'">'+ico(I[b.tone]||'',Z.badge_icon_list)+esc(b.short)+'</span>'}).join('')}
