function anyBad(l,scope){return badges(l,scope).some(function(b){return b.tone==='bad'})}

/* «График снижения цены» и current_price в «Реестре» — src/pricechart.js (EV_UI.price_chart, config/price_chart.json) */
function onOver(e){var bd=e.target.closest&&e.target.closest('.lcb');if(bd){var tip=bd.querySelector('.lctip');if(tip){bd.classList.remove('tipr');var r=bd.getBoundingClientRect();if(innerWidth-r.left<Z.tip_max+(B.tip_edge||24))bd.classList.add('tipr')}}}
document.addEventListener('mouseover',onOver);document.addEventListener('focusin',onOver);
/* тап по шильдику на телефоне: открыть/закрыть подсказку, не раскрывая лот */
document.addEventListener('click',function(e){var bd=e.target.closest&&e.target.closest('.lcb');document.querySelectorAll('.lcb.open').forEach(function(x){if(x!==bd)x.classList.remove('open')});if(bd){onOver({target:bd});bd.classList.toggle('open');e.stopPropagation();e.preventDefault()}},true);
