/* ---------- анализ материалов дела (Избранное), схема Юридического консультанта ---------- */
var FL={};((CA&&CA.flags)||[]).forEach(function(f){FL[f.id]=f});
function runTime(){return (CA&&CA.schedule&&CA.schedule.run_at_msk)||A.time||SC.fav_time}
/* типографика подписей из JSON: пробелы вокруг «/», неразрывный пробел после «п.», «ст.»… и перед «127-ФЗ», «ГК», «АПК» (текст схемы не меняется) */
function typo(s){s=String(s==null?'':s).replace(/\s*\/\s*/g,' / ');(A.nbsp_after||[]).forEach(function(w){s=s.split(w+' ').join(w+'\u00a0')});(A.nbsp_before||[]).forEach(function(w){s=s.split(' '+w).join('\u00a0'+w)});return s}
