 var flags=(a.flags||[]).map(function(x){var id=typeof x==='string'?x:x&&x.id,f=FL[id];return f?{id:id,level:f.level,text:f.text,norm:(cit&&f.norm_citizen)||f.norm,quote:(cit&&f.quote_citizen)||f.quote||'',mnote:f.manual_note||'',nv:f.not_verified,manual:!!f.manual,url:okUrl(x&&x.source_url)?x.source_url:'',date:x&&x.source_date||''}:null}).filter(Boolean);
 var fields=FD.map(function(f,i){var v=FV[f.id]||{},s=v.status;if(f.computed)s=a.run_at?ST[0]:ST[2];if(ST.indexOf(s)<0)s=ST[2];return {n:i+1,id:f.id,label:f.label,required:!!f.required,computed:!!f.computed,status:s,url:okUrl(v.source_url)?v.source_url:'',date:v.source_date||''}});
 /* обязательное поле без данных — в карточке «нет данных» и вывод «Недостаточно данных» (что бы ни пришло в verdict); необязательное пустое — скрыть */
 var missing=fields.filter(function(f){return f.required&&!f.computed&&f.status===ST[2]}).map(function(f){return f.label});
 if(Array.isArray(a.missing))a.missing.forEach(function(k){var f=FD.find(function(x){return x.id===k}),lb=f?f.label:k;if(missing.indexOf(lb)<0)missing.push(lb)});
